const modes={memory:'Cette fenêtre',browser:'Ce navigateur',available:'Tour disponible',syncing:'Conservation en cours',saved:'Conservé sur la tour',offline:'Tour indisponible',conflict:'À examiner'};
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const integer=value=>Number(value||0).toLocaleString('fr-FR');

export function continuityLabel(status){return modes[status.mode]||modes.browser;}
export function renderContinuityStatus({status,esc=escapeHTML,icon=()=>''}){
  return `<div class="continuity-state ${esc(status.mode)}" data-sync-mode="${esc(status.mode)}"><span class="continuity-state-light" aria-hidden="true"></span><div><span class="continuity-overline">LE JOURNAL DE L’ATELIER</span><h3>${continuityLabel(status)}</h3><p>${esc(status.message)}</p></div><div class="continuity-pending"><strong>${integer(status.pending)}</strong><span>opération${status.pending>1?'s':''}<br>en attente</span></div></div><div class="continuity-state-actions"><span>${status.lastSavedAt?'Dernier accusé reçu à '+new Date(status.lastSavedAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'La sauvegarde sur la tour attend son premier accusé.'}</span><button type="button" class="button ${status.mode==='available'?'button-red':''}" data-action="sync-connect" ${status.mode==='syncing'?'disabled':''}>${icon('link')} ${status.mode==='saved'?'Vérifier la conservation':'Relier le journal local'}</button><button type="button" class="button button-small" data-action="sync-inspect" ${status.mode==='syncing'?'disabled':''}>Actualiser</button></div>`;
}

export function renderAssetVault({status={},esc=escapeHTML,icon=()=>''}={}){
  return `<section class="asset-vault" aria-labelledby="asset-vault-title"><div class="continuity-heading"><div><p class="continuity-overline">LES FICHIERS ORIGINAUX</p><h3 id="asset-vault-title">LE COFFRE STL.</h3><p>Les fichiers accompagnent l’historique du projet. Chaque original conserve son identifiant et son empreinte.</p></div><span class="tag ${status.available?'tag-green':'tag-amber'}">${status.available?'COFFRE LOCAL DISPONIBLE':'COFFRE LOCAL À OUVRIR'}</span></div><p class="asset-vault-message" data-asset-vault-message role="status">${esc(status.message||(status.available?integer(status.fileCount)+' fichier(s) inscrits dans le coffre de cette tour.':'Le coffre est disponible depuis le dashboard installé sur le PC de l’atelier.'))}</p><div class="continuity-cards"><section><span class="continuity-overline">03 / TRANSFÉRER LES ORIGINAUX</span><h3>Depuis ce navigateur.</h3><p>Réunir les STL référencés par les dossiers et leur historique. L’export vérifie chaque fichier. Maximum : 256 Mio.</p><button type="button" class="button button-red" data-action="asset-browser-export" ${status.busy?'disabled':''}>${icon('save')} Exporter les STL du poste</button></section><section><span class="continuity-overline">04 / CONSERVER SUR LA TOUR</span><h3>Le coffre local.</h3><p>Copier les STL vers la tour, sauvegarder son coffre ou restaurer une archive de fichiers. Les associations sont immuables.</p><div class="form-actions"><button type="button" class="button" data-action="asset-vault-sync" ${status.busy||!status.available?'disabled':''}>${icon('upload')} Conserver les STL sur la tour</button><button type="button" class="button" data-action="asset-vault-export" ${status.busy||!status.available?'disabled':''}>${icon('save')} Sauvegarder le coffre</button><button type="button" class="button" data-action="asset-vault-restore" ${status.busy||!status.available?'disabled':''}>Restaurer une archive STL</button></div></section></div><p class="micro-copy">Le fichier .bojassets contient les STL et leurs empreintes. Le fichier JSON contient le journal, les dossiers et les versions. Conservez les deux ; pour changer de poste, restaurez le JSON puis l’archive STL dans le coffre local.</p><button type="button" class="button button-small" data-action="asset-vault-refresh" ${status.busy?'disabled':''}>${icon('rotate')} Vérifier le coffre local</button></section>`;
}

export function renderContinuityView({store,status,assetStatus={},esc=escapeHTML,icon=()=>''}){
  const journal=store.exportJournal(),conflicts=journal.operations.filter(op=>store._results.get(op.id)?.ok===false);
  return `<section class="continuity-view" aria-labelledby="continuity-title"><header class="continuity-heading"><div><p class="continuity-overline"><i></i> BOJ.ART / CONTINUITÉ</p><h2 id="continuity-title">REPRENDRE.<br><em>SANS PERDRE LE FIL.</em></h2><p>Le même historique pour les dossiers, les fiches du parc et les décisions de préparation.</p></div><div class="continuity-emblem" aria-hidden="true"><img src="./assets/logo.webp" alt=""><span>LE TRAVAIL<br>RESTE.</span></div></header>
    <section class="continuity-status-box" id="continuity-status" aria-live="polite">${renderContinuityStatus({status,esc,icon})}</section>
    <div class="continuity-metrics"><div><strong data-journal-count>${integer(journal.operations.length)}</strong><span>opérations conservées ici</span></div><div><strong>${integer(store.state.projects.length)}</strong><span>dossiers dans le journal</span></div><div><strong>${integer(store.state.machines.length)}</strong><span>emplacements de machines</span></div></div>
    <div class="continuity-cards"><section><span class="continuity-overline">01 / EMPORTER LE TRAVAIL</span><h3>Une sauvegarde<br>qui se relit.</h3><p>Exporter le journal complet pour retrouver les dossiers et les fiches. Une empreinte permet de vérifier que le fichier n’a pas été altéré.</p><button type="button" class="button button-red" data-action="backup-export">${icon('save')} Créer une sauvegarde</button></section><section><span class="continuity-overline">02 / RETROUVER UN HISTORIQUE</span><h3>Voir avant<br>de rapprocher.</h3><p>Ouvrir une sauvegarde, contrôler son contenu puis ajouter ses opérations. Les doublons sont conservés une seule fois.</p><button type="button" class="button" data-action="backup-import">${icon('upload')} Ouvrir une sauvegarde</button></section></div>
    <div id="backup-preview" aria-live="polite"></div><div id="continuity-error" role="alert" class="inline-error"></div>
    ${conflicts.length?`<details class="continuity-conflicts"><summary>${integer(conflicts.length)} opération(s) conservée(s), à examiner</summary><p>Le journal garde les deux intentions. Une modification devenue incompatible n’écrase pas la fiche plus récente.</p><ol>${conflicts.slice(-30).map(op=>`<li><strong>${esc(op.context.projectName||op.context.projectId)}${op.context.machineId?' / '+esc(op.context.machineId):''}</strong><p>${esc(store._results.get(op.id).message)}</p><small>${esc(op.type)} · ${new Date(op.at).toLocaleString('fr-FR')}</small></li>`).join('')}</ol></details>`:''}
    <div id="asset-vault-panel">${renderAssetVault({status:assetStatus,esc,icon})}</div>
    <footer class="continuity-footer"><div>${icon('folder')}<p><strong>Deux fichiers pour reprendre le projet.</strong><span>L’historique JSON et les originaux STL restent identifiés séparément. Ils ne contiennent ni clés d’accès ni état physique des imprimantes.</span></p></div><button type="button" class="button button-small" data-action="fleet">Les fiches du parc ${icon('arrow')}</button></footer>
    <details class="continuity-help"><summary>Comment fonctionne la conservation ?</summary><p>Le navigateur conserve le journal dès qu’il le peut. Le service installé sur la tour écrit les opérations dans une base locale avant d’en confirmer la réception. Le mode « Conservé sur la tour » apparaît seulement après cet accusé.</p><p>Sur la version hébergée de démonstration, le service de la tour n’est pas raccordé. Les sauvegardes téléchargeables restent utilisables. Une sauvegarde est un état à un instant donné ; conservez une copie sur un autre support.</p><p>Deux historiques d’atelier ayant des origines différentes ne sont pas fusionnés automatiquement. Le transfert vers un navigateur vierge se fait explicitement depuis l’aperçu de sauvegarde.</p></details>
  </section>`;
}

export function renderBackupPreview({inspection,store,filename,esc=escapeHTML,icon=()=>''}){
  const current=store.exportJournal(),incoming=inspection.journal;
  const sameSeed=current.seed.at===incoming.seed.at,blocked=!sameSeed&&current.operations.length>0;
  const existing=new Set(current.operations.map(op=>op.id));
  const duplicates=incoming.operations.filter(op=>existing.has(op.id)).length;
  return `<section class="backup-inspection" aria-labelledby="backup-inspection-title"><span class="continuity-overline">APERÇU / AUCUNE MODIFICATION APPLIQUÉE</span><h3 id="backup-inspection-title">${esc(filename)}</h3><p>Sauvegarde du ${new Date(inspection.backup.exportedAt).toLocaleString('fr-FR')} · empreinte du fichier vérifiée.</p><div class="backup-counts"><span><strong>${integer(inspection.summary.operations)}</strong> opérations</span><span><strong>${integer(inspection.summary.projects)}</strong> dossiers</span><span><strong>${integer(duplicates)}</strong> déjà présentes</span></div><p>${blocked?'Cette sauvegarde provient d’un autre atelier. Conservez le journal actuel ; le rapprochement est bloqué.':!sameSeed?'Ce navigateur n’a enregistré aucune opération. Restaurer adoptera explicitement l’origine de cette sauvegarde.':'Le rapprochement ajoute les opérations manquantes et conserve l’historique actuel.'}</p><p class="micro-copy">Les conflits de modification restent visibles dans le journal. L’empreinte vérifie l’intégrité du fichier ; elle ne prouve pas l’identité de son auteur.</p><div class="form-actions"><button type="button" class="button button-red" data-action="backup-restore" ${blocked?'disabled':''}>${icon('check')} ${sameSeed?'Ajouter à cet atelier':'Restaurer dans ce navigateur'}</button><button type="button" class="button" data-action="backup-cancel">Fermer l’aperçu</button></div></section>`;
}
